// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public {
        c = new Roulette{value: 10 ether}();
    }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.deal(actor, 20 ether);

        // first call in this block: succeeds in both P and M
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        // RULE: a second call within the SAME block.timestamp must revert
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        assertTrue(!ok2);
    }
}
